(()=>{const button=document.querySelector('.back-to-top');if(!button)return;const mobile=matchMedia('(max-width:760px)'),reduce=matchMedia('(prefers-reduced-motion:reduce)');let frame,tween;function update(){button.hidden=!mobile.matches||window.scrollY<Math.max(400,innerHeight*.7);frame=null}function schedule(){if(!frame)frame=requestAnimationFrame(update)}window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});window.addEventListener('pageshow',schedule);if(mobile.addEventListener)mobile.addEventListener('change',schedule);else mobile.addListener(schedule);function focusTop(){document.querySelector('header a')?.focus({preventScroll:true})}function stop(){tween?.kill();window.removeEventListener('touchstart',stop);window.removeEventListener('wheel',stop)}button.addEventListener('click',()=>{stop();if(window.gsap&&!reduce.matches){const position={y:window.scrollY};window.addEventListener('touchstart',stop,{passive:true,once:true});window.addEventListener('wheel',stop,{passive:true,once:true});tween=gsap.to(position,{y:0,duration:.65,ease:'power2.out',onUpdate:()=>window.scrollTo(0,position.y),onComplete:()=>{stop();window.scrollTo(0,0);focusTop();schedule()}})}else{window.scrollTo(0,0);focusTop();schedule()}});update()})();
